use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_HMD_log_in: Option<Common::EncryptedMessage_Impl>,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_HMD_log_in(container.api_HMD_log_in);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(HMD_log_in: Option<Common::EncryptedMessage_Impl>)
{
  put_HMD_log_in(HMD_log_in);
}

/// setter for IN EventDataPort
pub fn put_HMD_log_in(value: Option<Common::EncryptedMessage_Impl>)
{
  *extern_api::IN_HMD_log_in.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// getter for OUT EventDataPort
pub fn get_HMD_log_out() -> Option<Common::Log_Impl>
{
  return extern_api::OUT_HMD_log_out.lock().unwrap_or_else(|e| e.into_inner()).clone()
}
